export type TradeRegionSeed = {
  code: string;
  name: string;
  macroRegion: string;
  m49Code: string;
  countries: string[];
  characteristics: string[];
  sourceUrl: string;
};

export type BuyerPersonaSeed = {
  code: string;
  groupName: string;
  name: string;
  description: string;
  valueChainRole: string;
  customerGroups: string[];
  salesChannels: string[];
  purchaseScenarios: string[];
  buyingTriggers: string[];
  orderCharacteristics: string[];
  complianceFocus: string[];
  sourceRefs: string[];
};

export type ProductTrackSeed = {
  code: string;
  name: string;
  description: string;
  buyerValue: string;
  complianceFocus: string[];
};

export type ProductFamilySeed = {
  code: string;
  trackCode: string;
  name: string;
  description: string;
  useScenarios: string[];
  complianceTags: string[];
  keywords: string[];
};

export type PersonaTrackAffinitySeed = {
  personaCode: string;
  regionCode: string;
  trackCode: string;
  relevanceScore: number;
  familyRole: "core" | "cross_sell" | "seasonal" | "test";
  rationale: string;
};

export type PersonaFamilyAffinitySeed = PersonaTrackAffinitySeed & {
  productFamilyCode: string;
};

