const familySeedByCode = new Map(PRODUCT_FAMILY_SEEDS.map((item) => [item.code, item]));

export const PERSONA_TRACK_AFFINITY_SEEDS: PersonaTrackAffinitySeed[] = Object.entries(PERSONA_FAMILY_FOCUS).flatMap(([personaCode, familyCodes]) => {
  const explicitLinks = AFFINITY_MAP[personaCode] ?? [];
  const coveredTrackCodes = new Set<string>();
  for (const productFamilyCode of familyCodes) {
    const productFamily = familySeedByCode.get(productFamilyCode);
    if (!productFamily) throw new Error(`画像 ${personaCode} 引用了不存在的产品家族 ${productFamilyCode}`);
    coveredTrackCodes.add(productFamily.trackCode);
  }
  return [...coveredTrackCodes].map((trackCode) => {
    const explicitLink = explicitLinks.find(([explicitTrackCode]) => explicitTrackCode === trackCode);
    return {
      personaCode,
      regionCode: "GLOBAL",
      trackCode,
      relevanceScore: explicitLink?.[1] ?? 55,
      familyRole: explicitLink?.[2] ?? "test",
      rationale: explicitLink
        ? "基于该画像的价值链角色、终端客群和具体产品家族建立的初始研究关系，需在目标地区用真实买家与询盘继续验证。"
        : "由具体产品家族的采购场景补充上级赛道关系，属于待验证假设，需用真实买家目录、询盘或订单继续验证。",
    };
  });
});

export const PERSONA_FAMILY_AFFINITY_SEEDS: PersonaFamilyAffinitySeed[] = Object.entries(PERSONA_FAMILY_FOCUS).flatMap(([personaCode, familyCodes]) => familyCodes.map((productFamilyCode) => {
  const productFamily = familySeedByCode.get(productFamilyCode);
  if (!productFamily) throw new Error(`画像 ${personaCode} 引用了不存在的产品家族 ${productFamilyCode}`);
  const trackLink = AFFINITY_MAP[personaCode]?.find(([trackCode]) => trackCode === productFamily.trackCode);
  return {
    personaCode,
    regionCode: "GLOBAL",
    trackCode: productFamily.trackCode,
    productFamilyCode,
    relevanceScore: trackLink?.[1] ?? 55,
    familyRole: trackLink?.[2] ?? "test",
    rationale: "基于该画像的采购场景与产品家族边界建立的初始关系，属于待验证假设，需用真实买家目录、询盘或订单升级证据状态。",
  };
}));

export function regionCodeForCountry(country: string) {
  const code = country.trim().toUpperCase();
  return TRADE_REGION_SEEDS.find((region) => region.code !== "GLOBAL" && region.countries.includes(code))?.code ?? "GLOBAL";
}

