export function suggestPersonaCode(...values: string[]) {
  const text = values.join(" ").toLocaleLowerCase();
  return PERSONA_KEYWORDS.find(([, keywords]) => keywords.some((keyword) => text.includes(keyword.toLocaleLowerCase())))?.[0] ?? "GEN_IMPORT";
}
